    "/api/v1/metrics/push": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Receive the queue worker's exposition payload so it can be merged into the
         *     single scrape target above.
         *
         *     The worker has no HTTP server (`NestFactory.createApplicationContext`) and
         *     Render background workers accept no inbound connections, so its metrics are
         *     otherwise unreachable. Same bearer token as the scrape endpoint — this
         *     accepts data that ends up in the metrics feed, so it must not be more open
         *     than the feed itself.
         *
         *     Throttling is skipped: the worker pushes on a fixed 30s cadence and must
         *     never be rate-limited into silence.
         */
        post: operations["ObservabilityController_ingestWorkerMetrics"];
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
